// Locale metadata and the translation packs for the locales beyond the en/de
// reference pair, which stays inline in main.ts. The kernel supports seven
// locales (src/kernel/system/locale.ts); these packs bring the desktop Studio
// chrome to parity. Any key missing from a pack falls back to English at render
// time via t(), so partial translations degrade gracefully.
//
// Machine-translated; flagged for native review before the parity idea is
// promoted (ideas/distribution/desktop-locale-parity.md).

export type Locale = "en" | "de" | "es" | "fr" | "pt" | "zh" | "ja";

// Selectable order in the language switcher.
export const LOCALES: Locale[] = ["en", "de", "es", "fr", "pt", "zh", "ja"];

// Endonyms shown in the switcher — each language names itself.
export const LOCALE_LABELS: Record<Locale, string> = {
  en: "English",
  de: "Deutsch",
  es: "Español",
  fr: "Français",
  pt: "Português",
  zh: "中文",
  ja: "日本語",
};

